  "contradictory_card_ids": ["C63"],
  "prediction_basis_card_ids": ["C22", "C28", "C12", "C15", "C37", "C56", "C60", "C61", "C71", "C76", "C80", "C16", "C21", "C36", "C40", "C44", "C70", "C81"],
  "claims": [
    {
      "claim": "Dideoxyadenosine, a purine nucleoside, showed 38% ± 15% oral bioavailability in fasting patients, and additional dog/mouse records report F of 38–93%, all above the 20% threshold.",
      "card_ids": ["C22", "C37", "C56", "C60", "C61", "C71"]
    },
    {
      "claim": "Didanosine, the deaminated metabolite of ddA, has reported oral bioavailability of 30–54%, also above threshold.",
      "card_ids": ["C76"]
    },
    {
      "claim": "Emtricitabine, a polar nucleoside analog, showed 92% fasted oral bioavailability.",
      "card_ids": ["C28", "C80"]
    },
    {
      "claim": "Acyclovir, a guanine nucleoside analog, has human F of 0.2 (20%), at the threshold and not affirmatively below it.",
      "card_ids": ["C12"]
    },
    {
      "claim": "Gaultherin, a glycoside, has predicted human F of 20–30%, at or above threshold.",
      "card_ids": ["C15"]
    },
    {
      "claim": "The only low-F record, PMEA (C63), is a charged nucleotide phosphonate, not a nucleoside, and is not transferable to guanosine.",
      "card_ids": ["C63"]
    },
    {
      "claim": "SGLT2 inhibitor glycoside contexts consistently report F of 31–97.5%, supporting that polar glycosides can be orally bioavailable, though structural transferability to guanosine is moderate.",
      "card_ids": ["C16", "C21", "C36", "C40", "C70", "C81"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C37", "C56", "C60", "C61", "C71", "C76", "C80", "C36", "C40", "C44", "C70", "C81"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C63"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for guanosine itself is supplied.",
    "The low prior rests on physicochemical descriptors (logD, TPSA, HBD/HBA), not measured absorption or first-pass data.",
    "Transfer evidence comes from other nucleosides and glycosides; guanosine-specific transporter or metabolism data are absent.",
    "Acyclovir F of 20% sits exactly at the threshold, so threshold-boundary uncertainty remains.",
    "PMEA low F (C63) is a charged nucleotide phosphonate and not directly transferable to guanosine."
  ],
  "decision_summary": "New L2 records add further nucleoside F values (ddA/ddI 30–93%, emtricitabine 92%) and consistently high glycoside F values, all supporting F >= 20%; the only low-F card (PMEA) is a charged phosphonate with low transferability. The low physicochemical prior is insufficient to predict low, so prediction remains high with moderate confidence."
}

